#include <deque>

template <typename T>
class QueueBox {
private:
    std::deque<T> items;

public:
    bool isEmpty() const { return items.empty(); }
    void enqueue(T item) { items.push_back(item); }

    T dequeue() {
        T front = items.front();
        items.pop_front();
        return front;
    }

    T peek() const { return items.front(); }
    int size() const { return (int)items.size(); }
};

