    std::queue<std::string> queue;
    visited.insert(start);
    queue.push(start);
    while (!queue.empty()) {
        std::string node = queue.front();
        queue.pop();
        std::cout << node << "\n";
        for (const std::string& neighbor : graph.at(node)) {
            if (!visited.count(neighbor)) {
                visited.insert(neighbor);
                queue.push(neighbor);
